import {providerName,providerCopy,mapConfigured,locationNotice} from '/shared/map-provider.js';
import {getPreferences,updatePreferences} from '/shared/preferences.js';
import {localSearchHTML,bindLocalSearch,matchingPoints} from './search.js';
import {$,esc,icon,toast} from '/shared/ui.js';
import {campusMap,inCampus} from '/shared/map.js';
import {distance,direction,meters} from '/shared/routing.js';
import {routeSteps,guidance} from '/shared/guidance.js';
import {mapApps} from '/shared/map-apps.js';
import {locationFor} from '/shared/tencent-location.js';
import {voiceHTML,mountVoice,navigationPrompts} from '/shared/navigation-voice.js';

export function journeyHTML(catalog,targetId){const points=catalog.points.filter(p=>p.open),options=selected=>points.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('');return `<section class="journey-heading"><div><span class="eyebrow">CAMPUS WALK / 校园步行</span><h1>想去哪里？<span>我们一起走。</span></h1><p>选好目的地，先看路线，再从身边的小路出发。</p></div><a href="#routes" class="button secondary">${icon('camera')} 选一段拍摄探索</a></section><div class="journey-layout"><section class="journey-controls">${localSearchHTML('journey-search','搜索校园目的地')}<div id="journey-search-results" class="local-search-results" hidden></div><div class="journey-addresses"><span class="journey-thread" aria-hidden="true"></span><label class="journey-address"><b class="address-dot start"></b><span>从哪里出发<select id="journey-from" disabled><option value="">请选择起点</option><option value="gps">我的当前位置</option><option value="pick">在地图上选起点</option>${options('')}</select></span></label><label class="journey-address"><b class="address-dot end"></b><span>想去哪里<select id="journey-to" disabled><option value="">请选择目的地</option>${options(targetId)}</select></span></label></div><div class="journey-action-row"><button class="button secondary" id="journey-gps" disabled>${icon('pin')} 用我的位置</button><button class="button secondary" id="journey-pick" disabled>地图选起点</button></div><p class="journey-message" id="journey-message" role="status">正在准备${providerName(catalog)}，稍后可选择起点与目的地。</p><button class="button wide" id="journey-plan" disabled>${icon('walk')} 规划步行路线</button><section class="journey-result" id="journey-result" hidden><div class="journey-stats"><strong id="journey-time"></strong><span id="journey-distance"></span><small>${providerName(catalog).replace("地图","")}步行规划 · 预计时间</small></div><div class="journey-live"><b id="journey-symbol" aria-hidden="true">↑</b><p id="journey-instruction" aria-live="polite">路线已准备好</p></div><div class="journey-progress" aria-label="路线行进进度"><span id="journey-progress"></span></div><button class="button wide" id="journey-start">开始网页导航</button><div class="journey-action-row"><button class="button secondary" id="journey-follow">跟随位置：开</button><button class="button secondary" id="journey-voice">语音提示：关</button></div><details class="journey-steps"><summary>查看转向步骤</summary><ol id="journey-steps"></ol></details><p class="muted">路线、步行距离与预计时间由${providerName(catalog).replace("地图","")}提供，请确认现场入口及通行条件。</p></section>${voiceHTML()}<button class="text-btn wide" id="journey-apps">用手机地图 App / 网页版打开 ↗</button><p class="journey-privacy">${locationNotice(catalog)}算路会提供起终点坐标。本项目不保存导航位置，轨迹记录需另行开启。切到后台停止定位，请保持页面在前台。</p></section><section class="journey-map-panel"><div id="journey-map" class="map-canvas" role="region" aria-label="校园步行路线规划地图"></div><div class="journey-map-top"><span>${icon('walk')} 步行 · 北方民族大学</span><button class="button secondary small" id="journey-overview">全校范围</button></div><div class="journey-map-caption"><i></i>${providerName(catalog).replace("地图","")}步行路线 <span>现场入口与通行情况请自行确认</span></div></section></div><p class="journey-data" id="journey-data"></p>`;}

export async function mountJourney(catalog){
 let origin=null,position=null,leg=null,picking=false,watch=null,token=0,destroyed=false,follow=getPreferences().mapFollow,voice=false,lastSpoken='',lastSpeechAt=0,offCount=0,permissionPending=false,oneShot=0,planToken=0,replanning=false,lastReplan=0;
 const el=$('#journey-map'),geo=locationFor(catalog);
 const narrator=await mountVoice({onError:text=>toast(text),onChange:()=>{lastSpoken="";lastSpeechAt=0;prepareRoute();}});
 if(!el?.isConnected){narrator.destroy();return {destroy(){},refresh(){}};}
 const map=await campusMap(el,catalog,{canPick:()=>picking,onPick:p=>{if(!picking||destroyed)return false;if(!inCampus(p,catalog.campus)){message('请在北方民族大学校区内选择起点');return false;}stop();origin={...p,name:'地图选定起点'};picking=false;$('#journey-from').value='pick';message('起点已选择，可以规划路线');plan();},onPoint:id=>{if(picking){const p=catalog.points.find(p=>p.id===id);stop();origin=p;picking=false;$('#journey-from').value=id;message('已选起点：'+p.name);plan();}else{$('#journey-to').value=id;stop();plan();}}});
 if(!el.isConnected){map.destroy();narrator.destroy();return {destroy(){},refresh(){}};}

 const from=$('#journey-from'),to=$('#journey-to'),result=$('#journey-result'),start=$('#journey-start');
 const message=text=>{$('#journey-message').textContent=text;};
 bindLocalSearch($('#journey-search'),q=>{const box=$('#journey-search-results');box.hidden=!q;box.innerHTML=q?matchingPoints(catalog.points.filter(p=>p.open),q).map(p=>`<button type="button" class="button secondary small" data-destination="${esc(p.id)}">${esc(p.name)}</button>`).join('')||'<p>没有找到这个目的地。</p>':'';box.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{to.value=b.dataset.destination;stop();plan();});},$('#journey-search input')?.value||'');
 const target=()=>catalog.points.find(p=>p.id===to.value&&p.open);
 function silence(){narrator.stop();lastSpoken='';}
 function stop(){token++;if(watch!==null){geo.clearWatch(watch);watch=null;}permissionPending=false;silence();start.textContent='开始网页导航';start.disabled=!leg?.available;}
 function invalidate(){planToken++;stop();replanning=false;leg=null;result.hidden=true;map.navigation(null);$('#journey-plan').disabled=false;$('#journey-plan').innerHTML=icon('walk')+' 规划步行路线';}
 function prepareRoute(){if(destroyed||!leg?.available)return;const first=leg.steps?.find(s=>s.instruction)?.instruction; if(first)narrator.prepare(first);}
 function describe(){const total=leg.lengthWithApproach;$('#journey-time').textContent=Math.max(1,Math.ceil(leg.duration??total/75))+' 分钟';$('#journey-distance').textContent=meters(total);$('#journey-instruction').textContent='路线已准备好，开启定位后为你指路';$('#journey-symbol').textContent='↑';$('#journey-progress').style.width='0%';const steps=routeSteps(leg.path);$('#journey-steps').innerHTML=leg.steps?.length?leg.steps.map(s=>'<li>'+esc(s.instruction)+'</li>').join('')+`<li>确认 ${esc(target().name)} 的现场入口</li>`:`<li>从起点朝${direction(leg.path[0],leg.path[1]||target()).name}沿道路出发</li>`+steps.map(s=>`<li>${s.symbol} 行进至约 ${meters(s.along)} 处${s.action}</li>`).join('')+`<li>到达道路终点后，确认 ${esc(target().name)} 的现场入口${leg.approach>20?'（存在虚线靠近段）':''}</li>`;start.disabled=false;result.hidden=false;prepareRoute();}
 async function plan(){
  invalidate();const dest=target();if(!origin){message('先选择起点，或点击「用我的位置」');return;}if(!dest){message('请选择开放的目的地');return;}if(!inCampus(origin,catalog.campus)){message(providerCopy('当前位置在校园外，请用腾讯地图 App 前往校园。',catalog));return;}if(distance(origin,dest)<5){message('起点与目的地相同，请换一个目的地');return;}
  const id=++planToken;$('#journey-plan').disabled=true;$('#journey-plan').textContent=providerCopy('腾讯正在规划路线…',catalog);message(providerCopy('正在请求腾讯步行路线…',catalog));
  try{const next=await map.plan(origin,dest);if(destroyed||id!==planToken)return;leg=next;if(!leg.available){message(leg.reason+providerCopy('。可检查配置后重试或使用腾讯地图 App。',catalog));start.disabled=true;return;}describe();message(leg.policyWarning||leg.policyNote||(leg.endGap>30?providerCopy('腾讯路线已返回，终点距所选点位约 ',catalog)+meters(leg.endGap)+'，请确认可通行入口；未补画直线。':providerCopy('腾讯路线已规划，可查看步骤或开启网页导航。',catalog))); }
  catch{if(!destroyed&&id===planToken)message(providerCopy('腾讯路线请求失败，请重试',catalog));}
  finally{if(!destroyed&&id===planToken){$('#journey-plan').disabled=false;$('#journey-plan').innerHTML=icon('walk')+' 规划步行路线';}}
 }

 function gpsError(error){message(error.code===1?'定位权限未开启，可在浏览器设置中允许；也可以手动选起点。':'暂时无法获得位置，请到室外重试或手动选起点。');}
 function usePosition(){if(!mapConfigured(catalog)){message(providerCopy('腾讯地图尚未配置，请手动选起点或联系管理员',catalog));return;}invalidate();const id=++oneShot;permissionPending=true;message('正在获取位置，请允许浏览器定位…');$('#journey-gps').disabled=true;geo.getCurrentPosition(pos=>{if(destroyed||id!==oneShot)return;permissionPending=false;$('#journey-gps').disabled=false;const p={lng:pos.coords.longitude,lat:pos.coords.latitude,accuracy:pos.coords.accuracy,name:'当前位置',at:pos.timestamp};position=p;map.locate(p);if(p.accuracy>80){origin=null;message('定位精度约 '+Math.round(p.accuracy)+' 米，请到室外重试。暂不使用此位置规划。');return;}origin=p;from.value='gps';picking=false;plan();},e=>{if(destroyed||id!==oneShot)return;permissionPending=false;$('#journey-gps').disabled=false;gpsError(e);},{enableHighAccuracy:true,timeout:20000,maximumAge:3000});}
 function say(text){if(!voice||lastSpoken===text||Date.now()-lastSpeechAt<12000)return;lastSpoken=text;lastSpeechAt=Date.now();narrator.speak(text).then(ok=>{if(!ok&&lastSpoken===text){lastSpoken='';lastSpeechAt=0;}});}
 async function update(pos){const navigationToken=token;if(destroyed||!target())return;position={lng:pos.coords.longitude,lat:pos.coords.latitude,accuracy:pos.coords.accuracy,at:pos.timestamp,name:'当前位置'};map.locate(position,{follow});if(!inCampus(position,catalog.campus)){offCount=0;$('#journey-instruction').textContent='你在校园范围外，校内导航已停止。可使用地图 App。';stop();return;}let info=guidance(leg,position,target());if(!info.valid){offCount=0;$('#journey-instruction').textContent=info.text;$('#journey-symbol').textContent='…';silence();return;}if(info.offRoute){offCount++;if(offCount>=2&&!replanning&&Date.now()-lastReplan>=30000){replanning=true;lastReplan=Date.now();message(providerCopy('位置偏离路线，腾讯正在重新规划…',catalog));const next=await map.plan(position,target(),{fit:false});if(destroyed||navigationToken!==token)return;replanning=false;leg=next;offCount=0;if(!leg.available){$('#journey-instruction').textContent=providerCopy('腾讯重算暂不可用，导航已停止，请重试或使用腾讯地图 App。',catalog);stop();return;}origin=position;from.value='gps';describe();info=guidance(leg,position,target());message('已根据当前位置重新规划路线');}else{info.text='位置偏离路线，正在确认定位或等待重算…';}}else offCount=0;$('#journey-instruction').textContent=info.text;$('#journey-symbol').textContent=info.symbol||'↑';if(info.progress)$('#journey-progress').style.width=Math.min(100,Math.round(info.progress.along/(info.progress.total||1)*100))+'%';if(info.remaining!==undefined){$('#journey-distance').textContent='剩余约 '+meters(info.remaining);$('#journey-time').textContent=Math.max(1,Math.ceil(leg.duration?leg.duration*info.remaining/(leg.length||1):info.remaining/75))+' 分钟';}if(!info.offRoute&&!info.arrived){say(info.speech||info.text);if(voice)narrator.prepare(info.nextSpeech||navigationPrompts.arrival);}if(info.arrived){stop();if(voice)narrator.speak(navigationPrompts.arrival);$('#journey-progress').style.width='100%';message('本次导航已结束。请确认现场入口；探索任务需要自行完成。');}start.textContent=watch===null?'开始网页导航':'结束网页导航';}
 function begin(){if(watch!==null){stop();message('网页导航已停止，路线仍可查看');return;}if(!leg?.available||!target())return;if(!mapConfigured(catalog)){message(providerCopy('腾讯地图尚未配置，请联系管理员',catalog));return;}const id=++token;if(voice){narrator.speak(navigationPrompts.start);prepareRoute();}start.textContent='结束网页导航';$('#journey-instruction').textContent='正在请求定位，请允许浏览器访问位置…';watch=geo.watchPosition(p=>{if(destroyed||id!==token)return;update(p);},e=>{if(destroyed||id!==token)return;stop();gpsError(e);$('#journey-instruction').textContent='定位中断，导航已停止。可重试或查看路线步骤。';},{enableHighAccuracy:true,maximumAge:2000,timeout:20000});message('导航已开启。请保持页面在前台，本项目不保存导航位置。'+locationNotice(catalog));}
 function cancelPending(){oneShot++;$('#journey-gps').disabled=false;permissionPending=false;}
 from.onchange=()=>{cancelPending();invalidate();picking=false;origin=null;if(from.value==='gps')usePosition();else if(from.value==='pick'){picking=true;message('点击地图中的道路或点位，选择出发位置');}else{origin=catalog.points.find(p=>p.id===from.value&&p.open)||null;plan();}};
 to.onchange=()=>{stop();plan();};$('#journey-plan').onclick=plan;$('#journey-gps').onclick=usePosition;$('#journey-pick').onclick=()=>{cancelPending();invalidate();origin=null;picking=true;from.value='pick';message('点击地图中的道路或点位，选择出发位置');};start.onclick=begin;
 $('#journey-apps').onclick=()=>{const dest=target();if(!dest){message('先选一个目的地，再用地图打开');return;}mapApps(dest,watch!==null&&position?.accuracy<=80?position:origin,catalog.map);};$('#journey-overview').onclick=()=>map.overview();$('#journey-follow').textContent='跟随位置：'+(follow?'开':'关');$('#journey-follow').onclick=e=>{follow=!follow;updatePreferences({mapFollow:follow}).catch(error=>{if(destroyed)return;follow=getPreferences().mapFollow;$('#journey-follow').textContent='跟随位置：'+(follow?'开':'关');toast(error.message);});e.currentTarget.textContent='跟随位置：'+(follow?'开':'关');if(follow&&position)map.locate(position);};$('#journey-voice').onclick=e=>{voice=narrator.toggle();if(voice)prepareRoute();lastSpoken='';lastSpeechAt=0;e.currentTarget.textContent='语音提示：'+(voice?'开':'关');};
 from.disabled=false;to.disabled=false;$('#journey-gps').disabled=false;$('#journey-pick').disabled=false;$('#journey-plan').disabled=false;message('可选择校园点位作为起点，不开定位也能查看路线。');
 const hidden=()=>{if(document.hidden)narrator.stop();if(document.hidden&&(watch!==null||permissionPending||replanning)){cancelPending();planToken++;map.navigation(null);stop();message('页面已切到后台，定位已停止。返回后请重新开启导航。');}},unload=()=>{stop();oneShot++;};document.addEventListener('visibilitychange',hidden);window.addEventListener('pagehide',unload);
 $('#journey-data').textContent=providerName(catalog)+'提供地图与在线步行路线。'+locationNotice(catalog)+'网页提供前台位置跟随、偏航重算与语音提示，请以现场通行条件为准。';
 return {destroy(){if(destroyed)return;destroyed=true;planToken++;oneShot++;stop();narrator.destroy();document.removeEventListener('visibilitychange',hidden);window.removeEventListener('pagehide',unload);map.destroy();},refresh(next){catalog=next;const dest=target();if(to.value&&!dest){invalidate();message('该目的地已下线或关闭，请选择其他点位');}if(origin?.id&&!catalog.points.some(p=>p.id===origin.id&&p.open)){origin=null;invalidate();message('原起点已关闭，请重新选起点');}}};
}
